args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-11-05-kras-logo');D<-file.path(P,'work/2026-11-03-motif-source-search/inputs');.libPaths(c(file.path(P,'work/2026-10-28-sequence-figures/Rlib'),.libPaths()));library(ggseqlogo)
f<-readLines(file.path(D,'KRAS_SalidaAlignSE.fasta'));headers<-grepl('^>',f);ids<-sub('^>','',f[headers]);s<-vapply(split(f[!headers],cumsum(headers)[!headers]),paste0,collapse='',FUN.VALUE=character(1));stopifnot(length(s)==1354,length(unique(nchar(s)))==1,nchar(s[1])==188,length(ids)==1354)
F<-read.table(file.path(D,'KRAS_CharactPosDataN.tsv'),header=TRUE,check.names=FALSE);stopifnot(nrow(F)==188,identical(as.integer(F$Res),1:188),all(is.finite(as.matrix(F[c('ICMin','ICNeu','ICMax')]))))
pfm<-ggseqlogo:::makePFM(s,seq_type='aa');ic<-attr(pfm,'bits');height<-sweep(pfm,2,ic,'*');logo<-data.frame(position=rep(1:188,each=nrow(pfm)),residue=rep(rownames(pfm),188),frequency=as.vector(pfm),height_bits=as.vector(height));logo$block<-ifelse(logo$position<=99,'1-99','100-188');logo$local_position<-ifelse(logo$position<=99,logo$position,logo$position-99)
frust<-data.frame(position=rep(F$Res,3),state=rep(c('Minimum','Maximum','Neutral'),each=nrow(F)),value_bits=c(F$ICMin,F$ICMax,F$ICNeu));frust$block<-ifelse(frust$position<=99,'1-99','100-188');frust$local_position<-ifelse(frust$position<=99,frust$position,frust$position-99)
summary<-data.frame(position=1:188,non_gap=attr(pfm,'nongapped'),sequence_information_bits=ic,frustration_information_bits=F$ICTot,frustration_state=F$FrustEstado)
for(k in c('logo','frust','summary'))write.csv(get(k),file.path(P,'results/plot_data',paste0('kras_sequence_frustration_20261105_',k,'.csv')),row.names=FALSE)
saveRDS(list(sequences=s,ids=ids,pfm=pfm,logo=logo,frust=frust,summary=summary),file.path(W,'prepared-data.rds'));capture.output(sessionInfo(),file=file.path(W,'prepare-sessionInfo.txt'));cat('Author alignment1354x188;3760logo cells,564frustration values retained\n')
